void dei_system_rf_temp( void )
{		
  //if( !temperature.bit.in_sensor_present )
	if( !get_temp_sensor_present() )
	{
		notify_send( NOTIFY_ERROR , NOTIFY_PLD_ERROR_FEATURE_NA  ) ; 	
	}
	else
	{
	  //notify_send( NOTIFY_SHOW_TEMPERATURE , temperature.bit.in_value );
        os_tsk_wait(360);

		notify_send( NOTIFY_SHOW_TEMPERATURE , get_temp_sensor_value() );
	}
}

